#!/bin/bash
set -euo pipefail

# API Data Aggregation - Generated by flowsh
# Registry-based workflow execution script

echo "Starting workflow: API Data Aggregation"

# Workflow variables and state management
declare -A workflow_vars
declare -A workflow_state

# Color codes for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
NC='\033[0m'

# Configuration
VERBOSE=${VERBOSE:-false}
AGENT_TIMEOUT=${AGENT_TIMEOUT:-60}

# Environment Variables
HTTP_STATUS_CODE=${HTTP_STATUS_CODE:-""}
HTTP_RESPONSE_BODY=${HTTP_RESPONSE_BODY:-""}
HTTP_RESPONSE_TIME=${HTTP_RESPONSE_TIME:-""}
HTTP_RESPONSE_SIZE=${HTTP_RESPONSE_SIZE:-""}
HTTP_EFFECTIVE_URL=${HTTP_EFFECTIVE_URL:-""}
HTTP_REQUEST_METHOD=${HTTP_REQUEST_METHOD:-""}
HTTP_SUCCESS=${HTTP_SUCCESS:-""}
HTTP_ERROR=${HTTP_ERROR:-""}
ALL_API_DATA=${ALL_API_DATA:-""}
AVG_RESPONSE_TIME=${AVG_RESPONSE_TIME:-""}
SUMMARY_REPORT=${SUMMARY_REPORT:-""}

# =============================================================================
# UTILITY FUNCTIONS
# =============================================================================

# Logging functions with colors
log_info() {
    echo -e "${CYAN}ℹ️  $*${NC}"
}

log_success() {
    echo -e "${GREEN}✅ $*${NC}"
}

log_error() {
    echo -e "${RED}❌ $*${NC}" >&2
}

log_warning() {
    echo -e "${YELLOW}⚠️  $*${NC}" >&2
}

log_debug() {
    [[ "$VERBOSE" == "true" ]] && echo -e "${BLUE}🔍 DEBUG: $*${NC}" >&2 || true
}

log_step() {
    echo -e "${CYAN}🚀 $*${NC}"
}

# Operation logging with correlation IDs
log_operation_start() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    log_debug "$correlation_id" "Starting $operation_type: $operation_name"
}

log_operation_end() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    local status="${4:-success}"
    log_debug "$correlation_id" "Completed $operation_type: $operation_name ($status)"
}

# Enhanced error handling
handle_error() {
    local exit_code=$1
    local context="$2"
    local node_id="${3:-unknown}"
    
    case $exit_code in
        124)
            log_error "Timeout: $context took longer than ${AGENT_TIMEOUT}s (node: $node_id)"
            ;;
        127)
            log_error "Command not found in: $context (node: $node_id)"
            ;;
        1)
            log_error "General error in: $context (node: $node_id)"
            ;;
        *)
            log_error "Unknown error (exit code $exit_code) in: $context (node: $node_id)"
            ;;
    esac
    
    return $exit_code
}

# Variable management
set_workflow_var() {
    local var_name="$1"
    local var_value="$2"
    workflow_vars["$var_name"]="$var_value"
    log_debug "Set variable: $var_name = $var_value"
}

get_workflow_var() {
    local var_name="$1"
    local default_value="${2:-}"
    echo "${workflow_vars[$var_name]:-$default_value}"
}

# State management
set_workflow_state() {
    local state_key="$1"
    local state_value="$2"
    workflow_state["$state_key"]="$state_value"
    log_debug "Set state: $state_key = $state_value"
}

get_workflow_state() {
    local state_key="$1"
    local default_value="${2:-}"
    echo "${workflow_state[$state_key]:-$default_value}"
}

# Variable substitution in templates
substitute_variables() {
    local template="$1"
    local result="$template"
    
    # Find all variable references in the format {{#variable_name#}}
    while [[ $result =~ \{\{#([^#]+)#\}\} ]]; do
        local var_ref="${BASH_REMATCH[1]}"
        local var_value=$(get_workflow_var "$var_ref" "")
        
        if [[ -z "$var_value" ]]; then
            log_warning "Variable reference '$var_ref' not found, using empty string"
        fi
        
        # Escape special characters for sed
        local escaped_value=$(printf '%s\n' "$var_value" | sed 's/[[\.\*^\$()+?{|]/\\&/g')
        result=$(echo "$result" | sed "s|{{#${var_ref}#}}|$escaped_value|g")
    done
    
    echo "$result"
}

# Workflow Execution

# Node: fetch_weather

# Node: fetch_weather (Fetch Weather Data)
execute_http_fetch_weather() {
    log_step "🌐 HTTP Request: Fetch Weather Data"

    local url="https://api.openweathermap.org/data/2.5/weather?q=London&appid=${api_key}"
    local method="GET"
    local timeout=15
    local max_retries=2
    local retry_delay=2
    local error_handling="continue"

    # Validate URL is not empty
    if [[ -z "$url" ]]; then
        log_error "HTTP request URL is empty"
        return 1
    fi

    log_debug "Making $method request to: $url"
    
    # Prepare curl options with comprehensive configuration
    local curl_opts=(
        --max-time "$timeout"
        --retry "$max_retries" 
        --retry-delay "$retry_delay"
        --retry-max-time $((timeout * max_retries))
        --fail-with-body
        --silent --show-error --location
        --write-out "%{http_code};%{time_total};%{size_download};%{url_effective}"
    )

    # No authentication configured

    # No custom headers configured

    # No request body configured

    # Execute request with comprehensive error handling
    local response_file=$(mktemp)
    local metrics_file=$(mktemp)
    local stderr_file=$(mktemp)

    log_debug "Executing curl with options: ${curl_opts[*]}"
    
    if curl "${curl_opts[@]}" -X "$method" -o "$response_file" "$url" >"$metrics_file" 2>"$stderr_file"; then
        # Parse response and metrics
        local metrics=$(cat "$metrics_file" 2>/dev/null)
        local curl_stderr=$(cat "$stderr_file" 2>/dev/null)
        
        if [[ -n "$metrics" && "$metrics" =~ ^([0-9]{3})\;([0-9.]+)\;([0-9]+)\;(.*)$ ]]; then
            local http_code="${BASH_REMATCH[1]}"
            local time_total="${BASH_REMATCH[2]}"
            local size_download="${BASH_REMATCH[3]}"
            local effective_url="${BASH_REMATCH[4]}"
            
            local response_body=$(cat "$response_file" 2>/dev/null)

            # Set response variables
            set_workflow_var "http_status_code" "$http_code"
            set_workflow_var "http_response_body" "$response_body"
            set_workflow_var "http_response_time" "$time_total"
            set_workflow_var "http_response_size" "$size_download"
            set_workflow_var "http_effective_url" "$effective_url"
            set_workflow_var "http_request_method" "$method"

            # Handle success/error based on status code
            case "$http_code" in
                2*)
                    log_success "HTTP $method completed successfully (status: $http_code, time: ${time_total}s, size: ${size_download} bytes)"
                    set_workflow_var "http_success" "true"
                    set_workflow_var "http_error" ""
                    ;;
                3*)
                    log_info "HTTP $method returned redirect (status: $http_code)"
                    set_workflow_var "http_success" "true"
                    set_workflow_var "http_error" ""
                    ;;
                4*|5*)
                    log_error "HTTP $method failed with status $http_code"
                    set_workflow_var "http_success" "false"
                    set_workflow_var "http_error" "HTTP_${http_code}"

                    case "$error_handling" in
                        "ignore") 
                            log_info "Ignoring HTTP error as configured"
                            ;;
                        "continue") 
                            log_warning "Continuing despite HTTP error"
                            ;;
                        *)
                            cleanup_temp_files "$response_file" "$metrics_file" "$stderr_file"
                            return 1
                            ;;
                    esac
                    ;;
            esac
        else
            log_error "Failed to parse curl metrics: $metrics"
            set_workflow_var "http_success" "false"
            set_workflow_var "http_error" "PARSE_ERROR"
            cleanup_temp_files "$response_file" "$metrics_file" "$stderr_file"
            return 1
        fi
    else
        local curl_exit_code=$?
        local curl_stderr=$(cat "$stderr_file" 2>/dev/null)
        
        log_error "HTTP request failed (curl exit code: $curl_exit_code)"
        [[ -n "$curl_stderr" ]] && log_error "Curl error: $curl_stderr"
        
        set_workflow_var "http_success" "false"
        set_workflow_var "http_error" "CURL_${curl_exit_code}"
        set_workflow_var "http_status_code" "0"
        set_workflow_var "http_response_body" ""

        case "$error_handling" in
            "ignore")
                log_info "Ignoring curl error as configured"
                ;;
            "continue")
                log_warning "Continuing despite curl error"
                ;;
            *)
                cleanup_temp_files "$response_file" "$metrics_file" "$stderr_file"
                return 1
                ;;
        esac
    fi

    cleanup_temp_files "$response_file" "$metrics_file" "$stderr_file"
    
    log_debug "HTTP request completed, check http_success variable for result"
}

