        "sum")
            log_debug "Summing numeric values from ${#input_vars[@]} variables"
            local total=0
            local valid_count=0
            
            for var_name in "${input_vars[@]}"; do
                local value="$(get_workflow_var "$var_name" "0")"
                if [[ "$value" =~ ^[+-]?[0-9]+(.[0-9]+)?$ ]]; then
                    if command -v bc >/dev/null 2>&1; then
                        total=$(echo "$total + $value" | bc -l)
                    else
                        # Fallback to integer arithmetic if bc not available
                        total=$((total + ${value%.*}))
                    fi
                    ((valid_count++))
                else
                    log_warning "Skipping non-numeric value in $var_name: $value"
                fi
            done
            
            set_workflow_var "$output_var" "$total"
            log_success "Summed $valid_count numeric values, result: $total"
            ;;

        "avg")
            log_debug "Calculating average of numeric values from ${#input_vars[@]} variables"
            local total=0
            local valid_count=0
            
            for var_name in "${input_vars[@]}"; do
                local value="$(get_workflow_var "$var_name" "0")"
                if [[ "$value" =~ ^[+-]?[0-9]+(.[0-9]+)?$ ]]; then
                    if command -v bc >/dev/null 2>&1; then
                        total=$(echo "$total + $value" | bc -l)
                    else
                        total=$((total + ${value%.*}))
                    fi
                    ((valid_count++))
                else
                    log_warning "Skipping non-numeric value in $var_name: $value"
                fi
            done
            
            if [[ $valid_count -gt 0 ]]; then
                local average
                if command -v bc >/dev/null 2>&1; then
                    average=$(echo "scale=6; $total / $valid_count" | bc -l)
                else
                    average=$((total / valid_count))
                fi
                set_workflow_var "$output_var" "$average"
                log_success "Calculated average of $valid_count values: $average"
            else
                log_warning "No valid numeric values to average"
                set_workflow_var "$output_var" "0"
            fi
            ;;

        "collect")
            log_debug "Collecting values into JSON array from ${#input_vars[@]} variables"
            local -a collected=()
            
            for var_name in "${input_vars[@]}"; do
                local value="$(get_workflow_var "$var_name" "")"
                [[ -n "$value" ]] && collected+=("$value")
            done
            
            # Store as JSON array for structured access
            if command -v jq >/dev/null 2>&1; then
                local json_array
                json_array=$(printf '%s
' "${collected[@]}" | jq -R . | jq -s .)
                set_workflow_var "$output_var" "$json_array"
                log_success "Collected ${#collected[@]} values into JSON array"
            else
                # Fallback: create simple array format
                local array_string="["
                local first=true
                for value in "${collected[@]}"; do
                    if [[ "$first" == "true" ]]; then
                        first=false
                    else
                        array_string+=", "
                    fi
                    array_string+="\"$value\""
                done
                array_string+="]"
                set_workflow_var "$output_var" "$array_string"
                log_success "Collected ${#collected[@]} values into array (jq not available, using fallback format)"
            fi
            ;;

        "merge")
            log_debug "Merging JSON objects from ${#input_vars[@]} variables"
            local merged_json="{}"
            local merge_count=0
            
            if command -v jq >/dev/null 2>&1; then
                for var_name in "${input_vars[@]}"; do
                    local value="$(get_workflow_var "$var_name" "{}")"
                    # Validate that value is valid JSON
                    if echo "$value" | jq -e . >/dev/null 2>&1; then
                        merged_json=$(jq -s '.[0] * .[1]' <<< "$merged_json $value" 2>/dev/null)
                        if [[ $? -eq 0 ]]; then
                            ((merge_count++))
                        else
                            log_warning "Failed to merge JSON from $var_name"
                        fi
                    else
                        log_warning "Invalid JSON in variable $var_name, skipping"
                    fi
                done
                
                set_workflow_var "$output_var" "$merged_json"
                log_success "Merged $merge_count JSON objects"
            else
                log_error "jq is required for merge operation but not available"
                set_workflow_var "$output_var" "{}"
                return 1
            fi
            ;;

        *)
            log_error "Unknown aggregation method: $method"
            return 1
            ;;
    esac

    log_success "Variable aggregation completed: ${#input_vars[@]} inputs -> $output_var"
}

# Node: create_summary

# Node: create_summary (Create Summary Report)
execute_template_transform_create_summary() {
    log_step "🔧 Template Transform: Create Summary Report"

    local output_var="summary_report"
    local template_content=""

    # Inline template content
    template_content=''
    log_debug "Using inline template content"

    # Validate template was resolved
    if [[ -z "$template_content" ]]; then
        log_error "Failed to resolve template content"
        set_workflow_var "$output_var" ""
        return 1
    fi

    log_debug "Template resolved, length: ${#template_content} characters"

    # Apply template parameters (basic substitution)
    local rendered_content="$template_content"

    # No template parameters configured
    log_debug "No template parameters to process"

    # Advanced template functions processing
    rendered_content=$(process_template_functions "$rendered_content")
    
    # Additional variable substitution for workflow variables
    rendered_content=$(substitute_variables "$rendered_content")

    # Set output variable
    set_workflow_var "$output_var" "$rendered_content"

    log_success "Template transformed and stored in $output_var"
    log_debug "Template output length: ${#rendered_content} characters"
}

# Advanced template function processor for node create_summary
process_template_functions_create_summary() {
    local content="$1"

    # {{#date}} -> current date (YYYY-MM-DD)
    content="${content//\{\{#date\}\}/$(date '+%Y-%m-%d')}"

    # {{#time}} -> current time (HH:MM:SS)
    content="${content//\{\{#time\}\}/$(date '+%H:%M:%S')}"

    # {{#datetime}} -> current date and time (ISO 8601)
    content="${content//\{\{#datetime\}\}/$(date -Iseconds)}"

    # {{#timestamp}} -> current Unix timestamp
    content="${content//\{\{#timestamp\}\}/$(date '+%s')}"

    # {{#uuid}} -> generate UUID (fallback if uuidgen not available)
    if command -v uuidgen >/dev/null 2>&1; then
        content="${content//\{\{#uuid\}\}/$(uuidgen)}"
    else
        # Fallback UUID generation using date and random
        local fallback_uuid="uuid-$(date +%s)-$RANDOM"
        content="${content//\{\{#uuid\}\}/$fallback_uuid}"
    fi

    # {{#random}} -> random number (0-32767)
    content="${content//\{\{#random\}\}/$RANDOM}"

    # {{#hostname}} -> current hostname
    content="${content//\{\{#hostname\}\}/$(hostname 2>/dev/null || echo 'unknown')}"

    # {{#user}} -> current user
    content="${content//\{\{#user\}\}/$(whoami 2>/dev/null || echo 'unknown')}"

    # {{#pwd}} -> current working directory
    content="${content//\{\{#pwd\}\}/$(pwd)}"

    # Process variable-based functions with regex matching
    # {{#base64:variable}} -> base64 encode variable
    while [[ "$content" =~ \{\{#base64:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            if command -v base64 >/dev/null 2>&1; then
                encoded_value="$(echo -n "$var_value" | base64 -w 0)"
            else
                log_warning "base64 command not available, skipping encoding for $var_name"
                encoded_value="$var_value"
            fi
        fi
        
        content="${content//\{\{#base64:$var_name\}\}/$encoded_value}"
    done

    # {{#url_encode:variable}} -> URL encode variable
    while [[ "$content" =~ \{\{#url_encode:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            # Simple URL encoding (encode spaces and special characters)
            encoded_value="$(echo "$var_value" | sed 's/ /%20/g; s/&/%26/g; s/?/%3F/g; s/=/%3D/g')"
        fi
        
        content="${content//\{\{#url_encode:$var_name\}\}/$encoded_value}"
    done

    # {{#upper:variable}} -> uppercase variable
    while [[ "$content" =~ \{\{#upper:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local upper_value=""
        
        if [[ -n "$var_value" ]]; then
            upper_value="$(echo "$var_value" | tr '[:lower:]' '[:upper:]')"
        fi
        
        content="${content//\{\{#upper:$var_name\}\}/$upper_value}"
    done

    # {{#lower:variable}} -> lowercase variable
    while [[ "$content" =~ \{\{#lower:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local lower_value=""
        
        if [[ -n "$var_value" ]]; then
            lower_value="$(echo "$var_value" | tr '[:upper:]' '[:lower:]')"
        fi
        
        content="${content//\{\{#lower:$var_name\}\}/$lower_value}"
    done

    # {{#length:variable}} -> length of variable
    while [[ "$content" =~ \{\{#length:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local length_value="${#var_value}"
        
        content="${content//\{\{#length:$var_name\}\}/$length_value}"
    done

    # {{#json_escape:variable}} -> JSON escape variable
    while [[ "$content" =~ \{\{#json_escape:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local escaped_value=""
        
        if [[ -n "$var_value" ]]; then
            # Basic JSON escaping
            escaped_value="$(echo "$var_value" | sed 's/\\/\\\\/g; s/"/\\"/g; s/\t/\\t/g; s/\n/\\n/g; s/\r/\\r/g')"
        fi
        
        content="${content//\{\{#json_escape:$var_name\}\}/$escaped_value}"
    done

    echo "$content"
}

# Use the node-specific template function processor
process_template_functions() {
    process_template_functions_create_summary "$1"
}

# Node: end
echo "${summary_report}"

echo "Workflow completed successfully"
exit 0
